{
  "name": "Kepco BOP 20-20M 双极性可编程电源/电流源",
  "name_en": "Kepco BOP 20-20M Bipolar Programmable Power Supply / Current Source",
  "manufacturer": "Kepco",
  "description": "Kepco BOP 20-20M 是一款双极性可编程电源，可作为受控电流源使用，并支持测量电流、电压及电阻等量。在实验室中常用于为器件提供正负双向激励、进行电学表征和 I-V/R 测量。",
  "description_en": "The Kepco BOP 20-20M is a bipolar programmable power supply that can be used as a controlled current source and can measure current, voltage, and resistance-related quantities. In the lab it is commonly used to apply positive and negative electrical excitation to devices and for electrical characterization such as I-V and resistance measurements.",
  "tag_hints": [
    "bipolar power supply",
    "current source",
    "source-measure",
    "electrical characterization",
    "I-V measurement",
    "programmable power supply"
  ],
  "actions": [
    {
      "action_name": "auto-seti",
      "description": "设置输出电流",
      "description_en": "Set the output current"
    },
    {
      "action_name": "auto-measurei",
      "description": "测量电流",
      "description_en": "Measure current"
    },
    {
      "action_name": "auto-measurev",
      "description": "测量电压",
      "description_en": "Measure voltage"
    },
    {
      "action_name": "auto-measureR",
      "description": "测量电阻",
      "description_en": "Measure resistance"
    }
  ]
}

